CREATE FUNCTION protect_catalog_frozen() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.approved_at IS NOT NULL THEN RAISE EXCEPTION 'catalog_version_frozen_create_successor'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; IF NEW.status='approved' AND (NEW.approved_at IS NULL OR NEW.approved_by IS NULL OR NEW.content_hash IS NULL OR NEW.evidence_version_id IS NULL) THEN RAISE EXCEPTION 'catalog_approval_evidence_required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER material_spec_versions_catalog_frozen BEFORE UPDATE OR DELETE ON material_spec_versions FOR EACH ROW EXECUTE FUNCTION protect_catalog_frozen();
CREATE TRIGGER product_variant_versions_catalog_frozen BEFORE UPDATE OR DELETE ON product_variant_versions FOR EACH ROW EXECUTE FUNCTION protect_catalog_frozen();
CREATE TRIGGER product_assets_catalog_frozen BEFORE UPDATE OR DELETE ON product_assets FOR EACH ROW EXECUTE FUNCTION protect_catalog_frozen();
CREATE TRIGGER edge_treatment_versions_catalog_frozen BEFORE UPDATE OR DELETE ON edge_treatment_versions FOR EACH ROW EXECUTE FUNCTION protect_catalog_frozen();
CREATE TRIGGER finish_spec_versions_catalog_frozen BEFORE UPDATE OR DELETE ON finish_spec_versions FOR EACH ROW EXECUTE FUNCTION protect_catalog_frozen();
CREATE TRIGGER glyph_assets_catalog_frozen BEFORE UPDATE OR DELETE ON glyph_assets FOR EACH ROW EXECUTE FUNCTION protect_catalog_frozen();
CREATE FUNCTION protect_confirmed_sample() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.confirmed_at IS NOT NULL THEN RAISE EXCEPTION 'confirmed_sample_frozen'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER selected_samples_frozen BEFORE UPDATE OR DELETE ON selected_samples FOR EACH ROW EXECUTE FUNCTION protect_confirmed_sample();
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='schubert_app') THEN GRANT SELECT,INSERT,UPDATE ON buildings,floors,rooms,material_specs,material_spec_versions,product_variants,product_variant_versions,product_assets,edge_treatment_versions,finish_spec_versions,glyph_assets,material_boards,selected_samples TO schubert_app; END IF; END $$;
